#include <iostream>
#include <string>

class SimpleDate {
private:
    int month;
    int day;
    int year;

    static bool isLeapYear(int y) {
        return (y % 400 == 0) || (y % 100 != 0 && y % 4 == 0);
    }

    static int daysInMonth(int m, int y) {
        static const int daysPerMonth[] = {0, 31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
        if (m == 2 && isLeapYear(y)) return 29;
        return daysPerMonth[m];
    }

    void helpIncrement() {
        if (day < daysInMonth(month, year)) {
            ++day;
        } else {
            day = 1;
            if (month < 12) {
                ++month;
            } else {
                month = 1;
                ++year;
            }
        }
    }

public:
    SimpleDate(int m = 1, int d = 1, int y = 1900) : month(m), day(d), year(y) {}

    // Prefix increment: returns reference to *this (lvalue)
    SimpleDate& operator++() {
        helpIncrement();
        return *this;
    }

    // Postfix increment: dummy int parameter, returns unincremented value
    SimpleDate operator++(int) {
        SimpleDate temp = *this;
        helpIncrement();
        return temp;
    }

    friend std::ostream& operator<<(std::ostream& os, const SimpleDate& d) {
        static const std::string monthNames[] = {
            "", "January", "February", "March", "April", "May", "June",
            "July", "August", "September", "October", "November", "December"
        };
        os << monthNames[d.month] << ' ' << d.day << ", " << d.year;
        return os;
    }
};

int main() {
    SimpleDate d(2, 28, 2024); // Leap year 2024
    std::cout << "Initial date: " << d << '\n';

    std::cout << "Prefix ++d:   " << ++d << " (leap day allowed)\n";
    std::cout << "Current date: " << d << '\n';

    std::cout << "Postfix d++:  " << d++ << " (original value returned)\n";
    std::cout << "After postfix: " << d << '\n';

    return 0;
}

#include <iostream>

class Tracker {
private:
    int id;
public:
    Tracker(int idVal = 0) : id(idVal) {
        std::cout << "Tracker " << id << " constructed\n";
    }
    ~Tracker() {
        std::cout << "Tracker " << id << " destructed\n";
    }
    int getId() const { return id; }
};

int main() {
    // 1. Scalar dynamic allocation with value initialization
    Tracker* singleItem = new Tracker(42);
    std::cout << "Single item ID: " << singleItem->getId() << '\n';
    delete singleItem;
    singleItem = nullptr; // Prevent dangling pointer

    std::cout << "---\n";

    // 2. Dynamic array allocation with C++11 list initialization
    const int count = 3;
    Tracker* itemArray = new Tracker[count]{101, 102, 103};

    std::cout << "Array element 1 ID: " << itemArray[1].getId() << '\n';

    // Must use delete[] for arrays to destruct all elements
    delete[] itemArray;
    itemArray = nullptr;

    return 0;
}
